package com.projectdark.mobile;
import android.content.Context;import android.graphics.*;import com.projectdark.mobile.world.*;import java.io.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class TempleMillesV213Test {
 Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("project_dark_f5m_v1",0).edit().clear().commit();F5mSaveStore.install(c);}
 void capture(GameView v,String name)throws Exception{Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));File f=new File("build/reports/horror-v179/v213/"+name+".png");f.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(f)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}b.recycle();}
 void gate(GameView v,boolean exit,String expected)throws Exception{TownInteriorDef d=TownInteriorTest.field(v,"townInterior");WorldRuntimeAdapter a=TownInteriorTest.field(v,"reagentShopAdapter");if(!exit&&d.mapId.endsWith("_lobby")){WorldCameraTransform.Point npc=a.worldToScreen(d.npcX(),d.npcY());TownInteriorTest.tap(v,npc.x,npc.y-24);TownInteriorTest.tick(v,240);assertEquals(expected,((RuntimeState)TownInteriorTest.field(v,"state")).currentMapId());return;}TempleRoutes.Gate g=null;for(TempleRoutes.Gate q:TempleRoutes.forRoom(d))if(q.exit==exit)g=q;assertNotNull(g);WorldCameraTransform.Point p=a.worldToScreen(g.x,g.y);assertTrue("visible walk threshold "+g.label,p.x>=25&&p.x<=935&&p.y>=10&&p.y<470);TownInteriorTest.tap(v,p.x,p.y);TownInteriorTest.tick(v,240);RuntimeState s=TownInteriorTest.field(v,"state");assertEquals(expected,s.currentMapId());}
 @Test public void npcAndDoorWalkingReachGodPurchaseBothResourcesReturnAndReenter()throws Exception{
  GameView v=new GameView(c);v.layout(0,0,960,540);v.setSkillTestMode(false);RuntimeState s=TownInteriorTest.field(v,"state");s.rpg().restoreProgression(99,1_000_000_000L);assertTrue(s.rpg().restoreJobCode("WARRIOR"));s.rpg().restoreBaseResources(4000,4000);s.applyDerivedGrowth();
  WorldRuntimeAdapter w=TownInteriorTest.field(v,"worldAdapter");s.player().x=TempleEntranceRenderer.X-128;s.player().y=TempleEntranceRenderer.Y+96;w.snapCameraToPlayer();capture(v,"entrance-full");WorldCameraTransform.Point p=w.worldToScreen(TempleEntranceRenderer.X,TempleEntranceRenderer.Y);TownInteriorTest.tap(v,p.x,p.y);TownInteriorTest.tick(v,300);assertEquals("milles_interior_temple_lobby",s.currentMapId());capture(v,"lobby-portals-guide");
  gate(v,false,"milles_interior_temple_hub");capture(v,"hub-portal-guide");TownInteriorDef hub=TownInteriorTest.field(v,"townInterior");assertTrue(hub.blocked(hub.npcU,hub.npcV));assertFalse(hub.blocked(17,23));
  gate(v,false,"milles_interior_temple_seo");capture(v,"seo-npc-exit");TownInteriorDef d=TownInteriorTest.field(v,"townInterior");WorldRuntimeAdapter a=TownInteriorTest.field(v,"reagentShopAdapter");p=a.worldToScreen(d.npcX(),d.npcY());TownInteriorTest.tap(v,p.x,p.y-24);TownInteriorTest.tick(v,240);TempleGrowthWindow win=TownInteriorTest.field(v,"templeWindow");assertTrue(win.isOpen());capture(v,"god-hp-mp-menu");TownInteriorTest.tap(v,680,435);TownInteriorTest.tap(v,680,435);TownInteriorTest.tap(v,450,165);TownInteriorTest.tap(v,680,435);TownInteriorTest.tap(v,680,435);assertEquals(4050,s.rpg().baseMaxHp());assertEquals(4025,s.rpg().baseMaxMp());assertEquals(996_000_000L,s.rpg().normalExp().longValue());win.close();
  gate(v,true,"milles_interior_temple_hub");gate(v,true,"milles_interior_temple_lobby");gate(v,true,WorldDef.ID);TownInteriorTest.tick(v,60);assertEquals(WorldDef.ID,s.currentMapId());assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView next=new GameView(c);next.layout(0,0,960,540);RuntimeState restored=TownInteriorTest.field(next,"state");assertEquals(4050,restored.rpg().baseMaxHp());assertEquals(4025,restored.rpg().baseMaxMp());assertEquals(996_000_000L,restored.rpg().normalExp().longValue());w=TownInteriorTest.field(next,"worldAdapter");p=w.worldToScreen(TempleEntranceRenderer.X,TempleEntranceRenderer.Y);TownInteriorTest.tap(next,p.x,p.y);TownInteriorTest.tick(next,300);assertEquals("milles_interior_temple_lobby",restored.currentMapId());
 }
 @Test public void recoveredBackArchKeepsAllThreeOriginalStonePillars()throws Exception{Bitmap b;try(InputStream in=c.getAssets().open("temple-v211/entrance_arch_back.png")){b=BitmapFactory.decodeStream(in);}for(int[] q:new int[][]{{30,64},{64,56},{100,52}}){assertEquals("source stone pillar remains visible",255,Color.alpha(b.getPixel(q[0],q[1])));}for(int y=38;y<=65;y++)assertEquals(255,Color.alpha(b.getPixel(30,y)));}
 @Test public void entranceArchesFitInsideWorldAndStaticRoutesAreReused(){assertTrue(TempleEntranceRenderer.X+236*8f/7f<WorldDef.MAX_X);for(float[] foot:TempleEntranceRenderer.archFeet()){assertTrue(foot[0]>WorldDef.MIN_X);assertTrue(foot[2]<WorldDef.MAX_X);}for(TownInteriorDef d:TownInteriorDef.TEMPLE)assertSame(TempleRoutes.forRoom(d),TempleRoutes.forRoom(d));}
 @Test public void allGateContactsAreWalkableAndDoNotReplaceNpcTiles(){for(TownInteriorDef d:TownInteriorDef.TEMPLE){for(TempleRoutes.Gate g:TempleRoutes.forRoom(d)){assertTrue(d.mapId+g.label,d.navigationTiles().stream().anyMatch(t->t.x==g.x&&t.y==g.y));assertTrue(Math.hypot(g.x-d.npcX(),g.y-d.npcY())>20);}assertFalse(d.blocked(d.customerU,d.customerV));}}
 @Test public void inspectWholeVillageDistrictsAndStableRenderer()throws Exception{GameView v=new GameView(c);v.layout(0,0,960,540);WorldRuntimeAdapter w=TownInteriorTest.field(v,"worldAdapter");String[] names={"center","north-services","west-crafts","south-residences","east-waterside","river-bridge","temple"};float[][] spots={{768,560},{1040,320},{220,740},{800,1150},{1800,860},{2048,400},{TempleEntranceRenderer.X,TempleEntranceRenderer.Y}};for(int i=0;i<spots.length;i++){w.camera().snapTo(spots[i][0],spots[i][1]);capture(v,names[i]);}}
}
